selector_to_html = {"a[href=\"#id6\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">\u63a8\u7406<a class=\"headerlink\" href=\"#id6\" title=\"Link to this heading\">#</a></h3><p>\u9700\u8981 vLLM-FL \u73af\u5883</p>", "a[href=\"#id8\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">\u5f3a\u5316\u5b66\u4e60<a class=\"headerlink\" href=\"#id8\" title=\"Link to this heading\">#</a></h3><p>\u9700\u8981 verl-FL \u73af\u5883</p>", "a[href=\"#id7\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">\u670d\u52a1<a class=\"headerlink\" href=\"#id7\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#id3\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">\u4efb\u52a1\u7ea7 YAML<a class=\"headerlink\" href=\"#id3\" title=\"Link to this heading\">#</a></h3><p>\u4ee5 <code class=\"docutils literal notranslate\"><span class=\"pre\">examples/qwen3/conf/serve/8b.yaml</span></code> \u4e3a\u4f8b\u8bf4\u660e\u6b64\u914d\u7f6e\u6587\u4ef6\u3002</p><p>\u4efb\u52a1\u7ea7 YAML \u6587\u4ef6\u6307\u5b9a\u6a21\u578b\u3001\u6570\u636e\u96c6\u4ee5\u53ca\u8bad\u7ec3\u6216\u63a8\u7406\u7b49\u5177\u4f53\u4efb\u52a1\u7684\u53c2\u6570\u3002\u6b64\u6587\u4ef6\u4e2d\u7684\u6bcf\u4e2a\u53c2\u6570\u90fd\u76f4\u63a5\u6620\u5c04\u5230\u540e\u7aef\u5f15\u64ce\u63a5\u53d7\u7684\u53c2\u6570\uff0c\u5176\u4e2d\u8fde\u5b57\u7b26\uff08-\uff09\u66ff\u6362\u4e3a\u4e0b\u5212\u7ebf\uff08\\_\uff09\u3002</p>", "a[href=\"#id2\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">\u5b9e\u9a8c\u7ea7 YAML<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h3><p>\u4ee5 <code class=\"docutils literal notranslate\"><span class=\"pre\">examples/qwen3/conf/serve.yaml</span></code> \u4e3a\u4f8b\u8bf4\u660e\u6b64\u914d\u7f6e\u6587\u4ef6\u3002</p><p>\u5b9e\u9a8c\u7ea7\u6587\u4ef6\u662f <code class=\"docutils literal notranslate\"><span class=\"pre\">flagscale</span></code> \u547d\u4ee4\u7684\u5165\u53e3\u3002\u5b83\u5b9a\u4e49\u4e86\u8fd0\u884c\u7684\u5168\u5c40\u4e0a\u4e0b\u6587\uff1a</p>", "a[href=\"#id4\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u7b2c\u4e8c\u6b65\uff1a\u8fd0\u884c\u4efb\u52a1<a class=\"headerlink\" href=\"#id4\" title=\"Link to this heading\">#</a></h2><p>FlagScale \u4e3a\u5404\u79cd\u4efb\u52a1\u63d0\u4f9b\u7edf\u4e00\u7684\u8fd0\u884c\u5668\uff0c\u5305\u62ec\u8bad\u7ec3\u3001\u63a8\u7406\u3001\u5f3a\u5316\u5b66\u4e60\u548c\u670d\u52a1\u3002\u53ea\u9700\u6307\u5b9a\u914d\u7f6e\u6587\u4ef6\uff0c\u5373\u53ef\u901a\u8fc7\u4e00\u6761 <code class=\"docutils literal notranslate\"><span class=\"pre\">flagscale</span></code> \u547d\u4ee4\u8fd0\u884c\u4efb\u52a1\u3002\u8fd0\u884c\u5668\u4f1a\u81ea\u52a8\u52a0\u8f7d\u914d\u7f6e\u5e76\u6267\u884c\u4efb\u52a1\u3002\u4ee5\u4e0b\u5404\u8282\u6f14\u793a\u5982\u4f55\u8fd0\u884c\u5206\u5e03\u5f0f\u8bad\u7ec3\u4efb\u52a1\u3002</p>", "a[href=\"#id1\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u7528\u6237\u6307\u5357<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><p>\u672c\u6307\u5357\u4ecb\u7ecd\u5982\u4f55\u914d\u7f6e FlagScale \u4ee5\u53ca\u5982\u4f55\u8fd0\u884c\u8bad\u7ec3\u3001\u63a8\u7406\u3001\u670d\u52a1\u548c\u5f3a\u5316\u5b66\u4e60\u4efb\u52a1\u3002</p>", "a[href=\"#id5\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">\u8bad\u7ec3<a class=\"headerlink\" href=\"#id5\" title=\"Link to this heading\">#</a></h3><p>\u9700\u8981 Megatron-LM-FL \u73af\u5883</p>", "a[href=\"#yaml\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u7b2c\u4e00\u6b65\uff1a\u914d\u7f6e YAML \u6587\u4ef6<a class=\"headerlink\" href=\"#yaml\" title=\"Link to this heading\">#</a></h2><p>FlagScale \u4f7f\u7528 <a class=\"reference external\" href=\"https://hydra.cc/\">Hydra</a> \u8fdb\u884c\u914d\u7f6e\u7ba1\u7406\u3002\u6bcf\u4e2a\u4efb\u52a1\u7531\u4e24\u4e2a\u534f\u540c\u5de5\u4f5c\u7684 YAML \u6587\u4ef6\u9a71\u52a8\uff1a\u4e00\u4e2a\u5b9e\u9a8c\u7ea7\u6587\u4ef6\u548c\u4e00\u4e2a\u4efb\u52a1\u7ea7\u6587\u4ef6\uff0c\u5747\u4f4d\u4e8e <code class=\"docutils literal notranslate\"><span class=\"pre\">examples/</span></code> \u76ee\u5f55\u4e0b\u3002\u8fd0\u884c\u4efb\u52a1\u524d\uff0c\u9700\u8981\u5148\u914d\u7f6e\u8fd9\u4e9b\u6587\u4ef6\u3002</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
